head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16504";
scwin.edu_rnd = null;
scwin.edu_rnd1 = null;
scwin.edu_rnd2 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.edu_rnd = $c.util.getComponent('edu_rnd');
        scwin.edu_rnd1 = $c.util.getComponent('edu_rnd1');
        scwin.edu_rnd2 = $c.util.getComponent('edu_rnd2');
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16504.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_disclsEduApctTpCd", fn: function(){ return ((dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '11' || (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '41'); } }, { id: "if_disclsEduApctTpCd_2", fn: function(){ return ((dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '12' || (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '42'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_55", entity: "dlt_educationList", countIds: [], cells: [{ childId: "option_57", fn: function (v, i) { return String(v("disclsEduApplSeq")) + "," + String(v("disclsEduAcptStrtDd")) + "," + String(v("disclsEduAcptEndDd")); } }, { childId: "__rc0", fn: function (v, i) { return String(v("disclsEduCrsNm")); } }] },
        { genId: "c_foreach_61", entity: "dlt_educationList", countIds: [], cells: [{ childId: "option_63", fn: function (v, i) { return String(v("disclsEduApplSeq")) + "," + String(v("disclsEduAcptStrtDd")) + "," + String(v("disclsEduAcptEndDd")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("disclsEduCrsNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Submit();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_32_onclick
 * @description img_32 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_32_onclick = async function(e){
    try {
        await scwin.findCompany()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16504.img_32_onclick' }); }
};

/**
 * @method
 * @name slc_gubun_onchange
 * @description slc_gubun 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_gubun_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.change(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16504.slc_gubun_onchange' }); }
};

/**
 * @method
 * @name slc_sltEduRnd1_onchange
 * @description slc_sltEduRnd1 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_sltEduRnd1_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.getDsclEduRct(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16504.slc_sltEduRnd1_onchange' }); }
};

/**
 * @method
 * @name slc_sltEduRnd2_onchange
 * @description slc_sltEduRnd2 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_sltEduRnd2_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.getDsclEduRct(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16504.slc_sltEduRnd2_onchange' }); }
};

/**
 * @method
 * @name img_85_onclick
 * @description img_85 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_85_onclick = async function(e){
    try {
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16504.img_85_onclick' }); }
};

/**
 * @method
 * @name img_88_onclick
 * @description img_88 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_88_onclick = function(e){
    try {
        scwin.reset()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16504.img_88_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Submit
 * @description Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Submit = async function () {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: "/support/eduRspnStaff.do",
        ref: "dma_SubmitReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name change
 * @description change 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.change = function (code) {
    const form = (document.eduForm || { elements: [] });
    if (code.value === '1') {
        scwin.edu_rnd.setStyle("display", 'none');
        scwin.edu_rnd1.setStyle("display", 'block');
        scwin.edu_rnd2.setStyle("display", 'none');
        $c.util.getComponent("slc_sltEduRnd2").setValue("");
        $c.util.getComponent('txt_dsclEduRct').setLabel("");
    } else {
        if (code.value === '2') {
            scwin.edu_rnd.setStyle("display", 'none');
            scwin.edu_rnd1.setStyle("display", 'none');
            scwin.edu_rnd2.setStyle("display", 'block');
            $c.util.getComponent("slc_sltEduRnd1").setValue("");
            $c.util.getComponent('txt_dsclEduRct').setLabel("");
        } else {
            scwin.edu_rnd.setStyle("display", 'block');
            scwin.edu_rnd1.setStyle("display", 'none');
            scwin.edu_rnd2.setStyle("display", 'none');
            $c.util.getComponent("slc_sltEduRnd1").setValue("");
            $c.util.getComponent("slc_sltEduRnd2").setValue("");
            $c.util.getComponent('txt_dsclEduRct').setLabel("");
        }
    }
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    const form = (document.eduForm || { elements: [] });
    const dsclEduGubun = $c.util.getComponent('slc_gubun').getValue();
    let arr;
    const today = $c.util.getComponent('dma_SubmitReq').get('today');
    let sdate = '';
    let edate = '';
    if (dsclEduGubun === '1') {
        arr = slc_sltEduRnd1.value.split(",");
    } else {
        if (dsclEduGubun === '2') {
            arr = slc_sltEduRnd2.value.split(",");
        } else {
            arr = slt_edu_rnd.value.split(",");
        }
    }
    if (arr !== "") {
        $c.util.getComponent('dma_SubmitReq').set('disclsEduApplSeq', arr[0]);
        sdate = arr[1];
        edate = arr[2];
        if (dsclEduGubun === '1') {
            form.action = 'eduRspnStaff.do';
            $c.util.getComponent('dma_SubmitReq').set('method', 'educationResponsibilityForm');
            await scwin.tx_fn_Submit();
        } else {
            form.action = 'eduChrgStaff.do';
            $c.util.getComponent('dma_SubmitReq').set('method', 'educationChargeForm');
            await scwin.tx_fn_Submit();
        }
    } else {
        if ($c.util.getComponent('dma_SubmitReq').get('txtisurCd')=== "") {
            await $c.win.alert("회사명을  선택해 주세요.");
            return;
        }
        if (dsclEduGubun === "") {
            await $c.win.alert("교육 구분을 선택해 주세요.");
            return;
        } else {
            await $c.win.alert("교육 회차를 선택해 주세요");
            return;
        }
    }
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.reset = function () {
    const form = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SubmitReq').reset();
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    scwin.edu_rnd.setStyle("display", 'block');
    scwin.edu_rnd1.setStyle("display", 'none');
    scwin.edu_rnd2.setStyle("display", 'none');
    t_dsclEduRct.innerHTML = "";
};

/**
 * @method
 * @name getDsclEduRct
 * @description get Dscl Edu Rct 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getDsclEduRct = function (obj) {
    const slt_edu_rnd = obj.value;
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    const arr = slt_edu_rnd.split(",");
    let sdate;
    let edate;
    if (arr !== "") {
        sdate = arr[1];
        edate = arr[2];
        t_dsclEduRct.innerHTML = "<b>제출 기간 : " + sdate + " ~ " + edate + "</b>";
    } else {
        t_dsclEduRct.innerHTML = "";
    }
};

/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCompany = async function () {
    const corpSearchURL = '/jldfil00033/jldfil00033.xml';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    scwin.setCorpInfo_recv(await $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "510", type: "pageFramePopup" }, { method: "loadInitPage" }));
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    $c.util.getComponent('dma_SubmitReq').set('txtisurCd', isurCd);
    $c.util.getComponent('dma_SubmitReq').set('txtfssUnqNo', fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comNm);
    $c.util.getComponent('dma_SubmitReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_SubmitReq').set('chkPop', 'Y');
};

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
